     1	import { GAME_PORT, type GameFamily } from "@/lib/games";
     2	
     3	/** What a connect address IS, so a row can label it rather than guess. */
     4	export type AddressLabel = "IP address" | "Connect" | "Website";
     5	
     6	/**
     7	 * The address a customer can actually reach a server on.
     8	 *
     9	 * Deliberately NOT `Server.ipAddress`: that column holds the internal
    10	 * 10.20.x.x address behind the host's NAT, which is unreachable from outside
    11	 * and would be worse than showing nothing. This is the same derivation the
    12	 * "your server is ready" email uses (lib/server-deployed-email.ts) — a
    13	 * dedicated IP if the server has one, otherwise the NODE's public IP with the
    14	 * forwarded port — so the dashboard and the email can never disagree about
    15	 * where to connect.
    16	 */
    17	export function connectAddress(s: {
    18	  gamePlanId: string | null;
    19	  subdomain: string | null;
    20	  sshPort: number | null;
    21	  dedicatedIp: { address: string } | null;
    22	  portForwards: { publicPort: number; guestPort: number }[];
    23	  node: { publicIp: string } | null;
    24	  osTemplate: { family: string } | null;
    25	  gamePlan: { gameFamily: string } | null;
    26	}, gameBase: string): { address: string | null; addressLabel: AddressLabel | null } {
    27	  const host = s.dedicatedIp?.address ?? s.node?.publicIp ?? null;
    28	
    29	  if (s.gamePlanId !== null) {
    30	    // A play subdomain is the address the customer was actually given, so it
    31	    // wins over the raw host:port even when both exist.
    32	    if (s.subdomain) return { address: `${s.subdomain}.${gameBase}`, addressLabel: "Connect" };
    33	
    34	    const family = (s.gamePlan?.gameFamily ?? s.osTemplate?.family ?? "") as GameFamily;
    35	    const gamePort = GAME_PORT[family];
    36	    if (gamePort && host) {
    37	      // A dedicated IP exposes the game port directly; a shared node exposes
    38	      // whatever public port the forward was allocated.
    39	      const port = s.dedicatedIp
    40	        ? gamePort.port
    41	        : s.portForwards.find((f) => f.guestPort === gamePort.port)?.publicPort ?? null;
    42	      if (port) return { address: `${host}:${port}`, addressLabel: "Connect" };
    43	    }
    44	    return host ? { address: host, addressLabel: "IP address" } : { address: null, addressLabel: null };
    45	  }
    46	
    47	  if (!host) return { address: null, addressLabel: null };
    48	  // A dedicated IP is reachable on the standard SSH port; a shared node needs
    49	  // the forwarded one.
    50	  if (s.dedicatedIp) return { address: host, addressLabel: "IP address" };
    51	  return { address: s.sshPort ? `${host}:${s.sshPort}` : host, addressLabel: "IP address" };
    52	}

