    18	/**
    19	 * Pure resolution of "what ip:port should this server's subdomain point at
    20	 * right now" — no I/O, fully unit-testable. Extracted out of syncGameServerDns
    21	 * so the branching (dedicated vs. NAT-with-forward vs. NAT-without-forward vs.
    22	 * suspended/deleting) can be tested directly.
    23	 *
    24	 * Matches on BOTH guestPort and protocol, not guestPort alone. Several
    25	 * families (cs2/tf2/l4d2/gmod/sdtd — see GAME_JOIN_PORT_OVERRIDE in
    26	 * lib/games.ts) bind the identical port NUMBER for two different services —
    27	 * RCON on tcp, the actual game on udp — so a server can legitimately hold two
    28	 * PortForward rows with the same guestPort and different protocol. Matching
    29	 * on guestPort alone would non-deterministically resolve to whichever forward
    30	 * happens to come first, sometimes handing out the RCON port as the "connect"
    31	 * address — the exact class of bug already found and fixed for the dashboard's
    32	 * raw-IP display 2026-09-06/07 (see joinPortFor's own doc comment). The
    33	 * caller MUST pass the join port+protocol (via `joinPortFor`), not the raw
    34	 * GAME_PORT/health-check port, for the same reason.
    35	 */
    36	export function resolveGameServerDnsTarget(input: DnsTargetInput): { ip: string; port: number } | null {
