async function freeMinecraftEntries(): Promise<{ list: DirEntry[]; modes: string[]; domain: string }> {
  const [domain, rows] = await Promise.all([
    getSetting("free_minecraft_domain", "play.nxeon.cloud"),
    db.freeMinecraftServer.findMany({
      where: { isPublic: true, status: "READY" }, orderBy: { createdAt: "desc" }, take: 48,
      select: { subdomain: true, name: true, activeGameType: true, publicTagline: true },
    }),
  ]);
