export async function FreeMinecraftTabContent({
  heroSlot,
}: {
  heroSlot?: React.ReactNode;
} = {}) {
  const [enabled, domain, dashboard] = await Promise.all([
    getSettingBool("free_minecraft_enabled", false),
    getSetting("free_minecraft_domain", "play.nxeon.cloud"),
    getFreeMinecraftDashboard(),
  ]);

  // Health is DB-only (samples/events the worker sweep wrote), so it costs no
  // extra SSH round trip to freemc-host. Never let it break the dashboard.
  const [settings, health] = dashboard
    ? await Promise.all([getFreeMinecraftSettings(), getFreeMinecraftHealth().catch(() => null)])
    : [null, null];

  if (!enabled) {
    return (
      <div className="card max-w-md text-sm text-slate-400">
        Free servers aren&apos;t open yet — check back soon.
      </div>
    );
  }

  if (dashboard && settings) {
    return (
      <FreeMcDashboard
        server={dashboard}
        domain={domain}
        schemaFields={settings.schema.fields}
        properties={settings.properties}
        presets={FREEMC_PRESETS}
        gameTypes={FREEMC_GAME_TYPES}
        gameModes={FREEMC_GAME_MODES}
        health={health}
      />
    );
  }

  return (
    <>
      {heroSlot}
      <FreeMinecraftCreateForm
        domain={domain}
        gameTypes={FREEMC_GAME_TYPES}
        gameModes={FREEMC_GAME_MODES}
        showPreview
      />
    </>
  );
}

