export async function ownServers(userId: string): Promise<OwnServer[]> {
  const [base, freeDomain] = await Promise.all([gameSubdomainBase().catch(() => ""), getSetting("free_minecraft_domain", "play.nxeon.cloud").catch(() => "play.nxeon.cloud")]);
  const [paid, free] = await Promise.all([
    db.server.findMany({
      where: { userId, gamePlan: { isNot: null }, status: { notIn: ["DELETING"] } },
      select: {
        id: true, name: true, label: true, subdomain: true, status: true, publicListing: true,
        gamePlan: { select: { gameFamily: true } }, listingMeta: { select: { hidden: true } },
      },
      orderBy: { createdAt: "asc" },
    }).catch(() => []),
    db.freeMinecraftServer.findMany({ where: { userId }, select: { id: true, name: true, subdomain: true, status: true, isPublic: true } }).catch(() => []),
  ]);
  const out: OwnServer[] = paid.map((s) => {
    const game = s.gamePlan?.gameFamily ?? "minecraft";
    const hidden = !!s.listingMeta?.hidden;
    const visible = s.publicListing && s.status === "RUNNING" && !!s.subdomain && !hidden;
    const note = !s.publicListing ? null
      : hidden ? "Hidden by Nxeon moderation. Contact support to find out why."
      : !s.subdomain ? "Needs a play address before it can be listed."
      : s.status !== "RUNNING" ? "Listed, but only shows while the server is running."
      : null;
    return {
      id: s.id, kind: "paid", game, name: s.label || s.name, address: s.subdomain && base ? `${s.subdomain}.${base}` : null,
      status: s.status, listed: s.publicListing, visible, hiddenByModeration: hidden,
      // Same key the directory builds for a paid entry (lib/server-directory-data.ts paidEntries).
      publicId: visible ? nxeonServerId(game, `p-${s.id.slice(0, 8)}`) : null, note,
    };
  });
  for (const f of free) {
    out.push({
      id: f.id, kind: "free", game: "minecraft", name: f.name || f.subdomain, address: `${f.subdomain}.${freeDomain}`,
      status: f.status, listed: f.isPublic, visible: f.isPublic && f.status === "READY", hiddenByModeration: false,
      publicId: null, note: f.isPublic && f.status !== "READY" ? "Listed, but only shows while the server is ready." : null,
    });
  }
  return out;
}

/** True when this directory entry is one of the user's own servers (paid listings only carry a public id). */
export function ownsEntry(own: OwnServer[], e: Pick<DirEntry, "publicId" | "address">): OwnServer | null {
  return own.find((o) => (o.publicId && o.publicId === e.publicId) || (!!o.address && o.address === e.address)) ?? null;
}

